-- City Challenge Season 5 (China) Champion Card Pad: Riven playmat. Safe to run more than once.
insert into promo_items (id, r, data)
select 'item-10780', 10780, $j${"cat": "COLLECTIBLE", "nm": "City Challenge Season 5 Champion Card Pad - Riven", "se": "N/A", "cn": "N/A", "ra": "N/A", "do": "N/A", "tg": "Playmat\nRiven\nCity Challenge\nChampion", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/city-challenge-season-5-champion-card-pad-riven-ch-item-10780.webp", "inf": "Champion prize playmat for City Challenge Season 5 in China (Oct 31, 2026 to Jan 10, 2027).", "r": 10780, "id": "item-10780", "la": "Chinese", "ev": "CC - China", "ty": "Playmat", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": ""}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10780' or (data->>'nm' = $n$City Challenge Season 5 Champion Card Pad - Riven$n$ and data->>'la' = 'Chinese'));
